// Extrai o arquivo PDF do payload do WhatsApp
// Suporta Z-API e Evolution API
const body = $input.first().json.body || $input.first().json;

// Z-API format
const zapiFile = body?.message?.documentMessage || body?.message?.imageMessage;
// Evolution format  
const evolutionFile = body?.data?.message?.documentMessage || body?.data?.message?.audioMessage;

const fileData = zapiFile || evolutionFile;
const senderPhone = body?.phone || body?.data?.key?.remoteJid?.replace('@s.whatsapp.net','') || '';
const fileName    = fileData?.fileName || fileData?.title || 'fatura.pdf';
const fileUrl     = fileData?.url || fileData?.directPath || '';
const mimetype    = fileData?.mimetype || '';
const caption     = body?.text || body?.caption || body?.data?.message?.conversation || '';

if (!fileUrl && !mimetype.includes('pdf')) {
  return [{ json: { ignorar: true, motivo: 'Mensagem sem PDF', phone: senderPhone } }];
}

// Extrair mês do caption se informado (ex: "Abril" ou "abril")
const mesesMap = { 'janeiro':'Janeiro','fevereiro':'Fevereiro','março':'Março','marco':'Março','abril':'Abril','maio':'Maio','junho':'Junho','julho':'Julho','agosto':'Agosto','setembro':'Setembro','outubro':'Outubro','novembro':'Novembro','dezembro':'Dezembro' };
const captionLower = caption.toLowerCase();
const mesCaption = Object.entries(mesesMap).find(([k]) => captionLower.includes(k))?.[1] || '';

return [{ json: { fileUrl, fileName, senderPhone, mesCaption, mimetype, caption, ignorar: false } }];

const texto      = $input.first().json.text || '';
const payload    = $('Extrair Payload WhatsApp').first().json;
const phone      = payload.senderPhone;
const mesCaption = payload.mesCaption || '';

const prompt = `Você é especialista em faturas bancárias brasileiras.

Analise a fatura e extraia TODOS os lançamentos. Identifique também o banco/cartão de origem.

Retorne SOMENTE JSON puro (sem markdown):
{"mes":"NomeDoMes","banco":"NomeDoBanco","periodo":"DD/MM/AAAA a DD/MM/AAAA","total_despesas":0.00,"total_receitas":0.00,"lancamentos":[{"data":"DD/MM/AAAA","descricao":"Nome max 50","categoria":"Alimentação|Moradia|Transporte|Saúde|Educação|Lazer|Vestuário|Assinaturas|Investimentos|Outros","tipo":"Despesa|Receita","valor":0.00,"forma_pagamento":"Crédito|Débito|Pix|Dinheiro|Boleto|Transferência","cartao":"NomeDoBanco","parcelas":1,"observacoes":""}]}

Regras: Ignore total, pagamento mínimo, saldo anterior, encargos, IOF. Estornos = Receita. campo cartao = mesmo que banco.

Texto da fatura:\n${texto}`;

return [{ json: { model: 'claude-opus-4-6', max_tokens: 8000, messages: [{ role: 'user', content: prompt }], _phone: phone, _mesCaption: mesCaption } }];

const resposta    = $input.first().json.content?.[0]?.text || '';
const promptNode  = $('Montar Prompt').first().json;
const phone       = promptNode._phone;
const mesCaption  = promptNode._mesCaption;

let dados;
try {
  const m = resposta.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('JSON não encontrado');
  dados = JSON.parse(m[0]);
} catch(e) {
  return [{ json: { erro: true, msg: e.message, phone } }];
}

const mMap = { 'janeiro':'Janeiro','fevereiro':'Fevereiro','março':'Março','marco':'Março','abril':'Abril','maio':'Maio','junho':'Junho','julho':'Julho','agosto':'Agosto','setembro':'Setembro','outubro':'Outubro','novembro':'Novembro','dezembro':'Dezembro' };
const mes   = mesCaption || mMap[(dados.mes||'').toLowerCase().trim()] || dados.mes || 'Indefinido';
const banco = dados.banco || 'N/A';

const lancamentos = (dados.lancamentos||[]).map(l => ({
  mes, banco,
  data:            l.data||'',
  descricao:       (l.descricao||'').substring(0,50),
  categoria:       l.categoria||'Outros',
  tipo:            l.tipo||'Despesa',
  valor:           parseFloat(l.valor)||0,
  forma_pagamento: l.forma_pagamento||'',
  cartao:          l.cartao||banco,
  parcelas:        parseInt(l.parcelas)||1,
  observacoes:     l.observacoes||''
}));

const tot_desp = lancamentos.filter(l=>l.tipo==='Despesa').reduce((s,l)=>s+l.valor,0);
const tot_rec  = lancamentos.filter(l=>l.tipo==='Receita').reduce((s,l)=>s+l.valor,0);

const por_cat = {};
lancamentos.forEach(l=>{ if(l.tipo==='Despesa') por_cat[l.categoria]=(por_cat[l.categoria]||0)+l.valor; });
const top_cat = Object.entries(por_cat).sort((a,b)=>b[1]-a[1]).slice(0,3);

const resumo_wpp = `✅ *Fatura processada!*\n\n🏦 *${banco}* – ${mes}\n📊 ${lancamentos.length} lançamentos\n\n💸 Despesas: R$ ${tot_desp.toFixed(2).replace('.',',')}\n💰 Receitas: R$ ${tot_rec.toFixed(2).replace('.',',')}\n📈 Saldo: R$ ${(tot_rec-tot_desp).toFixed(2).replace('.',',')}\n\n🔝 *Top categorias:*\n${top_cat.map(([c,v])=>`  • ${c}: R$ ${v.toFixed(2).replace('.',',')}`).join('\n')}\n\n_Lançamentos salvos no Google Sheets automaticamente_ ✓`;

return [{ json: { mes, banco, lancamentos, tot_desp, tot_rec, phone, resumo_wpp } }];
